async function registryXlsx(file) {
  const wb = new ExcelJS.Workbook();
  wb.creator = CUSTOMER; wb.lastModifiedBy = CUSTOMER; wb.created = new Date('2026-09-18T00:00:00Z'); wb.modified = wb.created;
  const head = (ws, cols) => {
    ws.columns = cols.map(([header, width]) => ({ header, width }));
    const r = ws.getRow(1);
    r.font = { bold: true }; r.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF3F3F1' } };
    r.alignment = { vertical: 'top', wrapText: true }; ws.views = [{ state: 'frozen', ySplit: 1 }];
  };
  const body = (ws) => ws.eachRow((row, n) => { if (n > 1) row.alignment = { vertical: 'top', wrapText: true }; });

  const about = wb.addWorksheet('О реестре');
  about.columns = [{ width: 110 }];
  [
    `Реестр доступов и секретов CRM «Учёткин», ${CUSTOMER}. Состояние на ${T}.`,
    'В реестре нет ни одного ключа и пароля — только где секрет лежит, кто им владеет, кто имеет доступ, каким должно быть целевое состояние по регламенту сопровождения (раздел 7) и когда менять.',
    'Лист «Реестр» — все доступы и секреты. Лист «Роли» — роли в облаке и репозитории на дату реестра; их сверяет с фактом исполнитель раз в квартал и при каждом обследовании.',
    'Столбец «Владелец» — кто выдаёт и отзывает доступ. «Целевое состояние» — как должно быть по регламенту; если оно отличается от столбца «Состояние», это шаг передачи из раздела 7 регламента.',
    'Реестр ведёт исполнитель; изменения показываются в ежемесячном отчёте. При смене исполнителя меняются все секреты с пометкой «при смене исполнителя».',
  ].forEach((t) => about.addRow([t]));
  about.getRow(1).font = { bold: true, size: 13 };
  about.eachRow((row) => { row.alignment = { vertical: 'top', wrapText: true }; });

  const reg = wb.addWorksheet('Реестр');
  head(reg, [['№', 5], ['Объект', 38], ['Тип', 14], ['Где лежит', 34], ['Владелец (выдаёт и отзывает)', 22], ['У кого доступ сейчас', 28], ['Целевое состояние по регламенту', 40], ['Ротация', 24], ['Как сменить или отозвать', 40], ['Состояние на ' + T, 30]]);
  REGISTRY.forEach((r, i) => reg.addRow([i + 1, ...r]));
  body(reg); reg.autoFilter = { from: 'A1', to: 'J1' };

  const roles = wb.addWorksheet('Роли');
  head(roles, [['Где', 34], ['Субъект', 26], ['Роли на ' + T, 60], ['Целевое состояние', 50]]);
  ROLES.forEach((r) => roles.addRow(r));
  body(roles);

  await wb.xlsx.writeFile(file);
}

